-- Receipt shape guards must not depend on SQL short-circuit evaluation.
DROP VIEW closing_issue_rows;
CREATE VIEW closing_issue_rows AS WITH book AS (SELECT * FROM books),
      active_sources AS (SELECT s.* FROM sources s JOIN book b ON b.id=s.book_id WHERE NOT EXISTS(SELECT 1 FROM bank_source_dispositions z WHERE z.book_id=s.book_id AND z.source_id=s.id) AND NOT EXISTS(SELECT 1 FROM fact_revision_lineage z WHERE z.old_book_id=s.book_id AND z.old_source_id=s.id)),
      active_drafts AS (SELECT d.* FROM drafts d JOIN active_sources s ON s.id=d.source_id AND s.book_id=d.book_id
        WHERE NOT EXISTS(SELECT 1 FROM ai_bank_links link WHERE link.bank_source_id=s.id AND link.book_id=s.book_id)),
      event_scope AS (SELECT e.*,b.id AS scope_book_id FROM business_events e JOIN book b ON b.firm_id=e.firm_id AND b.company_id=e.company_id
        WHERE substr(json_extract(CASE WHEN json_valid(e.payload) THEN e.payload ELSE 'null' END,'$.occurred_on'),1,7)=b.period OR EXISTS(SELECT 1 FROM business_mappings m WHERE m.event_id=e.id AND m.book_id=b.id)),
      issues AS (
      SELECT d.book_id AS book_id,'unreviewed' AS category,'draft' AS object_type,d.id AS object_id,'尚有未审核或未导出的有效凭证' AS detail FROM active_drafts d WHERE d.status<>'exported'
      UNION ALL SELECT s.book_id,'unprocessed','source',s.id,'来源尚未形成有效凭证草稿' FROM active_sources s WHERE NOT EXISTS(SELECT 1 FROM drafts d WHERE d.book_id=s.book_id AND d.source_id=s.id)
      UNION ALL SELECT s.book_id,'missing_evidence','source',s.id,'当前有效来源缺少原件或证据引用' FROM active_sources s WHERE trim(COALESCE((SELECT se.evidence_ref FROM source_evidence se WHERE se.book_id=s.book_id AND se.source_id=s.id ORDER BY se.id DESC LIMIT 1),s.evidence_ref))=''
      UNION ALL SELECT b.id,'business_pending','book',b.id,'本企业本期仍有未完成审批或移交的业务事项，请企业财务核对' FROM book b WHERE EXISTS(SELECT 1 FROM event_scope e WHERE e.scope_book_id=b.id AND e.status<>'handed_off')
      UNION ALL SELECT b.id,'missing_evidence','book',b.id,'本企业仍有发生日期缺失或无效的未移交资料，无法确定归期，请企业财务修正' FROM book b WHERE EXISTS(SELECT 1 FROM business_events e WHERE e.firm_id=b.firm_id AND e.company_id=b.company_id AND e.status<>'handed_off' AND NOT (COALESCE(length(json_extract(CASE WHEN json_valid(e.payload) THEN e.payload ELSE 'null' END,'$.occurred_on'))=10 AND json_extract(CASE WHEN json_valid(e.payload) THEN e.payload ELSE 'null' END,'$.occurred_on') GLOB '20[0-9][0-9]-[0-1][0-9]-[0-3][0-9]' AND strftime('%Y-%m-%d',json_extract(CASE WHEN json_valid(e.payload) THEN e.payload ELSE 'null' END,'$.occurred_on'),'+0 days')=json_extract(CASE WHEN json_valid(e.payload) THEN e.payload ELSE 'null' END,'$.occurred_on'),0)=1))
      UNION ALL SELECT m.book_id,'missing_evidence','event',m.event_id,'已移交事项缺少当前有效附件' FROM business_mappings m JOIN book b ON b.id=m.book_id
        WHERE NOT EXISTS(SELECT 1 FROM business_attachments a WHERE a.event_id=m.event_id AND NOT EXISTS(SELECT 1 FROM case_supersessions z WHERE z.event_id=a.event_id AND z.old_attachment_id=a.id))
      UNION ALL SELECT b.id,'open_cases','case',c.id,'本账套仍有未关闭的异常或补件待办' FROM case_tasks c JOIN book b ON c.book_id=b.id OR c.event_id IN(SELECT m.event_id FROM business_mappings m WHERE m.book_id=b.id) WHERE c.state<>'closed'
      UNION ALL SELECT b.id,'open_cases','book',b.id,'本企业本期未移交事项仍有待处理补件，请企业财务核对' FROM book b WHERE EXISTS(SELECT 1 FROM case_tasks c JOIN event_scope e ON e.id=c.event_id AND e.scope_book_id=b.id WHERE c.book_id IS NULL AND c.state<>'closed' AND NOT EXISTS(SELECT 1 FROM business_mappings m WHERE m.event_id=e.id AND m.book_id=b.id))
      UNION ALL SELECT m_book.book_id,'background_pending','ocr_job',q.id,'票据识别仍在运行或存在发送结果未知的任务' FROM ocr_jobs q JOIN event_scope e ON e.id=q.event_id JOIN business_mappings m_book ON m_book.event_id=e.id AND m_book.book_id=e.scope_book_id WHERE q.status IN ('queued','running','retry_wait') AND NOT EXISTS(SELECT 1 FROM case_supersessions z WHERE z.event_id=q.event_id AND z.old_attachment_id=q.attachment_id) AND EXISTS(SELECT 1 FROM business_mappings m JOIN book b ON b.id=m.book_id WHERE m.event_id=e.id)
      UNION ALL SELECT q.book_id,'background_pending','proposal_job',q.id,'分录任务仍在运行或等待人工处理' FROM proposal_jobs q JOIN book b ON b.id=q.book_id WHERE q.status IN ('waiting','queued','running','retry_wait') OR q.status IN ('needs_attention','interrupted','failed') AND EXISTS(SELECT 1 FROM drafts d WHERE d.id=q.draft_id AND d.book_id=q.book_id AND d.status='draft')
      UNION ALL SELECT m_book.book_id,'background_pending','event',r.event_id,'仍有未完成的模型执行记录' FROM ai_runs r JOIN event_scope e ON e.id=r.event_id JOIN business_mappings m_book ON m_book.event_id=e.id AND m_book.book_id=e.scope_book_id WHERE r.status='running' AND EXISTS(SELECT 1 FROM business_mappings m JOIN book b ON b.id=m.book_id WHERE m.event_id=e.id)
      UNION ALL SELECT m_book.book_id,'model_uncertain','event',c.event_id,'仍有模型外发结果或费用未知的记录' FROM model_costs c JOIN event_scope e ON e.id=c.event_id JOIN business_mappings m_book ON m_book.event_id=e.id AND m_book.book_id=e.scope_book_id WHERE c.state='uncertain' AND EXISTS(SELECT 1 FROM business_mappings m JOIN book b ON b.id=m.book_id WHERE m.event_id=e.id)
      UNION ALL SELECT s.book_id,'unmatched_bank','source',s.id,'银行来源未匹配业务事项，也未形成独立已导出的凭证' FROM active_sources s WHERE s.source_kind='bank' AND NOT EXISTS(SELECT 1 FROM ai_bank_links l WHERE l.bank_source_id=s.id AND l.book_id=s.book_id) AND NOT EXISTS(SELECT 1 FROM drafts d WHERE d.source_id=s.id AND d.book_id=s.book_id AND d.status='exported')
      UNION ALL SELECT s.book_id,'unmatched_bank','source',s.id,'银行收付核销尚未分配完整金额，待清偿事项仍须核对' FROM active_sources s WHERE s.source_kind='bank'
        AND EXISTS(SELECT 1 FROM settlement_allocations a WHERE a.book_id=s.book_id AND a.bank_source_id=s.id AND NOT EXISTS(SELECT 1 FROM settlement_reversals r WHERE r.allocation_id=a.id AND r.book_id=a.book_id))
        AND (SELECT COALESCE(sum(a.amount_cents),0) FROM settlement_allocations a WHERE a.book_id=s.book_id AND a.bank_source_id=s.id AND NOT EXISTS(SELECT 1 FROM settlement_reversals r WHERE r.allocation_id=a.id AND r.book_id=a.book_id))<>s.amount_cents
      UNION ALL SELECT m.book_id,'unmatched_business','event',m.event_id,'已支付业务事项尚未匹配银行来源，请先核对防止重复记账' FROM business_mappings m JOIN event_scope e ON e.id=m.event_id AND e.scope_book_id=m.book_id JOIN book b ON b.id=m.book_id
        WHERE json_extract(CASE WHEN json_valid(e.payload) THEN e.payload ELSE 'null' END,'$.payment_status')='paid' AND NOT EXISTS(SELECT 1 FROM ai_bank_links l WHERE l.event_id=m.event_id AND l.book_id=m.book_id)
        AND NOT EXISTS(SELECT 1 FROM fact_revision_lineage z WHERE z.old_book_id=m.book_id AND z.old_source_id=m.source_id)
      UNION ALL SELECT x.book_id,'delivery_pending','export',x.id,'导出后缺少内容一致的完整导入回执，或回执仍有未知及差异' FROM exports x JOIN book b ON b.id=x.book_id WHERE NOT EXISTS(SELECT 1 FROM delivery_manifests m JOIN delivery_receipts r ON r.export_id=m.export_id AND r.book_id=m.book_id
      WHERE m.export_id=x.id AND m.book_id=x.book_id AND json_extract(CASE WHEN json_valid(r.body_json) THEN r.body_json ELSE 'null' END,'$.book_id')=json_extract(CASE WHEN json_valid(m.payload_json) THEN m.payload_json ELSE 'null' END,'$.book_id') AND json_extract(CASE WHEN json_valid(r.body_json) THEN r.body_json ELSE 'null' END,'$.company_id')=json_extract(CASE WHEN json_valid(m.payload_json) THEN m.payload_json ELSE 'null' END,'$.company_id') AND json_extract(CASE WHEN json_valid(r.body_json) THEN r.body_json ELSE 'null' END,'$.period')=json_extract(CASE WHEN json_valid(m.payload_json) THEN m.payload_json ELSE 'null' END,'$.period') AND json_extract(CASE WHEN json_valid(r.body_json) THEN r.body_json ELSE 'null' END,'$.currency')=json_extract(CASE WHEN json_valid(m.payload_json) THEN m.payload_json ELSE 'null' END,'$.currency')
      AND NOT EXISTS(SELECT 1 FROM delivery_receipts newer WHERE newer.export_id=r.export_id AND newer.book_id=r.book_id AND (newer.created_at>r.created_at OR newer.created_at=r.created_at AND newer.id>r.id))
      AND (SELECT count(*) FROM json_each(CASE WHEN json_type(CASE WHEN json_valid(r.body_json) THEN r.body_json ELSE 'null' END,'$.items')='array' THEN json_extract(CASE WHEN json_valid(r.body_json) THEN r.body_json ELSE 'null' END,'$.items') ELSE '[]' END) i)=(SELECT count(*) FROM json_each(CASE WHEN json_type(CASE WHEN json_valid(m.payload_json) THEN m.payload_json ELSE 'null' END,'$.items')='array' THEN json_extract(CASE WHEN json_valid(m.payload_json) THEN m.payload_json ELSE 'null' END,'$.items') ELSE '[]' END) expected)
      AND (SELECT count(*) FROM json_each(CASE WHEN json_type(CASE WHEN json_valid(r.body_json) THEN r.body_json ELSE 'null' END,'$.items')='array' THEN json_extract(CASE WHEN json_valid(r.body_json) THEN r.body_json ELSE 'null' END,'$.items') ELSE '[]' END) i)=x.count
      AND NOT EXISTS(SELECT 1 FROM json_each(CASE WHEN json_type(CASE WHEN json_valid(r.body_json) THEN r.body_json ELSE 'null' END,'$.items')='array' THEN json_extract(CASE WHEN json_valid(r.body_json) THEN r.body_json ELSE 'null' END,'$.items') ELSE '[]' END) i
        WHERE json_extract(CASE WHEN json_valid(i.value) THEN i.value ELSE 'null' END,'$.status') IS NULL OR json_extract(CASE WHEN json_valid(i.value) THEN i.value ELSE 'null' END,'$.status')<>'accepted' OR trim(COALESCE(json_extract(CASE WHEN json_valid(i.value) THEN i.value ELSE 'null' END,'$.external_voucher_id'),''))=''
        OR (SELECT count(*) FROM json_each(CASE WHEN json_type(CASE WHEN json_valid(r.body_json) THEN r.body_json ELSE 'null' END,'$.items')='array' THEN json_extract(CASE WHEN json_valid(r.body_json) THEN r.body_json ELSE 'null' END,'$.items') ELSE '[]' END) duplicate WHERE json_extract(CASE WHEN json_valid(duplicate.value) THEN duplicate.value ELSE 'null' END,'$.draft_id')=json_extract(CASE WHEN json_valid(i.value) THEN i.value ELSE 'null' END,'$.draft_id'))<>1
        OR (SELECT count(*) FROM json_each(CASE WHEN json_type(CASE WHEN json_valid(r.body_json) THEN r.body_json ELSE 'null' END,'$.items')='array' THEN json_extract(CASE WHEN json_valid(r.body_json) THEN r.body_json ELSE 'null' END,'$.items') ELSE '[]' END) duplicate WHERE json_extract(CASE WHEN json_valid(duplicate.value) THEN duplicate.value ELSE 'null' END,'$.external_voucher_id')=json_extract(CASE WHEN json_valid(i.value) THEN i.value ELSE 'null' END,'$.external_voucher_id'))<>1
        OR EXISTS(SELECT 1 FROM delivery_receipt_items h WHERE h.book_id=r.book_id AND h.receipt_id<>r.id AND
          (h.claimed_draft_id<>json_extract(CASE WHEN json_valid(i.value) THEN i.value ELSE 'null' END,'$.draft_id') AND h.external_voucher_id=json_extract(CASE WHEN json_valid(i.value) THEN i.value ELSE 'null' END,'$.external_voucher_id')
           OR h.claimed_draft_id=json_extract(CASE WHEN json_valid(i.value) THEN i.value ELSE 'null' END,'$.draft_id') AND trim(COALESCE(h.external_voucher_id,''))<>'' AND h.external_voucher_id<>json_extract(CASE WHEN json_valid(i.value) THEN i.value ELSE 'null' END,'$.external_voucher_id')))
        OR NOT EXISTS(SELECT 1 FROM json_each(CASE WHEN json_type(CASE WHEN json_valid(m.payload_json) THEN m.payload_json ELSE 'null' END,'$.items')='array' THEN json_extract(CASE WHEN json_valid(m.payload_json) THEN m.payload_json ELSE 'null' END,'$.items') ELSE '[]' END) expected WHERE json_extract(CASE WHEN json_valid(expected.value) THEN expected.value ELSE 'null' END,'$.draft_id')=json_extract(CASE WHEN json_valid(i.value) THEN i.value ELSE 'null' END,'$.draft_id') AND (json_extract(CASE WHEN json_valid(i.value) THEN i.value ELSE 'null' END,'$.date')) IS (json_extract(CASE WHEN json_valid(expected.value) THEN expected.value ELSE 'null' END,'$.date')) AND (json_extract(CASE WHEN json_valid(i.value) THEN i.value ELSE 'null' END,'$.amount')) IS (json_extract(CASE WHEN json_valid(expected.value) THEN expected.value ELSE 'null' END,'$.amount')) AND (json_extract(CASE WHEN json_valid(i.value) THEN i.value ELSE 'null' END,'$.description')) IS (json_extract(CASE WHEN json_valid(expected.value) THEN expected.value ELSE 'null' END,'$.description'))
          AND (SELECT count(*) FROM json_each(CASE WHEN json_type(CASE WHEN json_valid(i.value) THEN i.value ELSE 'null' END,'$.lines')='array' THEN json_extract(CASE WHEN json_valid(i.value) THEN i.value ELSE 'null' END,'$.lines') ELSE '[]' END) line)=(SELECT count(*) FROM json_each(CASE WHEN json_type(CASE WHEN json_valid(expected.value) THEN expected.value ELSE 'null' END,'$.lines')='array' THEN json_extract(CASE WHEN json_valid(expected.value) THEN expected.value ELSE 'null' END,'$.lines') ELSE '[]' END) wanted)
          AND (SELECT count(*) FROM json_each(CASE WHEN json_type(CASE WHEN json_valid(i.value) THEN i.value ELSE 'null' END,'$.lines')='array' THEN json_extract(CASE WHEN json_valid(i.value) THEN i.value ELSE 'null' END,'$.lines') ELSE '[]' END) line)>=2
          AND NOT EXISTS(SELECT 1 FROM json_each(CASE WHEN json_type(CASE WHEN json_valid(i.value) THEN i.value ELSE 'null' END,'$.lines')='array' THEN json_extract(CASE WHEN json_valid(i.value) THEN i.value ELSE 'null' END,'$.lines') ELSE '[]' END) line WHERE NOT EXISTS(SELECT 1 FROM json_each(CASE WHEN json_type(CASE WHEN json_valid(expected.value) THEN expected.value ELSE 'null' END,'$.lines')='array' THEN json_extract(CASE WHEN json_valid(expected.value) THEN expected.value ELSE 'null' END,'$.lines') ELSE '[]' END) wanted
            WHERE (json_extract(CASE WHEN json_valid(line.value) THEN line.value ELSE 'null' END,'$.ordinal')) IS (json_extract(CASE WHEN json_valid(wanted.value) THEN wanted.value ELSE 'null' END,'$.ordinal')) AND (json_extract(CASE WHEN json_valid(line.value) THEN line.value ELSE 'null' END,'$.account_code')) IS (json_extract(CASE WHEN json_valid(wanted.value) THEN wanted.value ELSE 'null' END,'$.account_code')) AND (json_extract(CASE WHEN json_valid(line.value) THEN line.value ELSE 'null' END,'$.debit')) IS (json_extract(CASE WHEN json_valid(wanted.value) THEN wanted.value ELSE 'null' END,'$.debit')) AND (json_extract(CASE WHEN json_valid(line.value) THEN line.value ELSE 'null' END,'$.credit')) IS (json_extract(CASE WHEN json_valid(wanted.value) THEN wanted.value ELSE 'null' END,'$.credit')) AND json_type(CASE WHEN json_valid(line.value) THEN line.value ELSE 'null' END,'$.auxiliary_values')='object' AND (json_extract(CASE WHEN json_valid(line.value) THEN line.value ELSE 'null' END,'$.auxiliary_values.department')) IS (json_extract(CASE WHEN json_valid(wanted.value) THEN wanted.value ELSE 'null' END,'$.auxiliary_values.department')) AND (json_extract(CASE WHEN json_valid(line.value) THEN line.value ELSE 'null' END,'$.auxiliary_values.employee')) IS (json_extract(CASE WHEN json_valid(wanted.value) THEN wanted.value ELSE 'null' END,'$.auxiliary_values.employee')) AND (json_extract(CASE WHEN json_valid(line.value) THEN line.value ELSE 'null' END,'$.auxiliary_values.counterparty')) IS (json_extract(CASE WHEN json_valid(wanted.value) THEN wanted.value ELSE 'null' END,'$.auxiliary_values.counterparty')) AND (json_extract(CASE WHEN json_valid(line.value) THEN line.value ELSE 'null' END,'$.auxiliary_values.project')) IS (json_extract(CASE WHEN json_valid(wanted.value) THEN wanted.value ELSE 'null' END,'$.auxiliary_values.project')) AND (SELECT count(*) FROM json_each(CASE WHEN json_type(CASE WHEN json_valid(line.value) THEN line.value ELSE 'null' END,'$.auxiliary_values')='object' THEN json_extract(CASE WHEN json_valid(line.value) THEN line.value ELSE 'null' END,'$.auxiliary_values') ELSE '{}' END))=(SELECT count(*) FROM json_each(CASE WHEN json_type(CASE WHEN json_valid(wanted.value) THEN wanted.value ELSE 'null' END,'$.auxiliary_values')='object' THEN json_extract(CASE WHEN json_valid(wanted.value) THEN wanted.value ELSE 'null' END,'$.auxiliary_values') ELSE '{}' END)))
            OR (SELECT count(*) FROM json_each(CASE WHEN json_type(CASE WHEN json_valid(i.value) THEN i.value ELSE 'null' END,'$.lines')='array' THEN json_extract(CASE WHEN json_valid(i.value) THEN i.value ELSE 'null' END,'$.lines') ELSE '[]' END) duplicate_line WHERE json_extract(CASE WHEN json_valid(duplicate_line.value) THEN duplicate_line.value ELSE 'null' END,'$.ordinal')=json_extract(CASE WHEN json_valid(line.value) THEN line.value ELSE 'null' END,'$.ordinal'))<>1)))
    )
      UNION ALL SELECT b.id,'fact_revision','revision',r.id,'业务事实修订或已导出调整建议尚未完成独立处置' FROM fact_revisions r JOIN book b ON r.old_book_id=b.id OR r.target_book_id=b.id WHERE r.state IN ('pending','adjustment_proposed')
      ) SELECT issues.book_id,issues.category,issues.object_type,issues.object_id,issues.detail FROM issues ORDER BY issues.category,issues.object_type,issues.object_id;
